{
  "assessment": "High inflation (32.3%) driven by price pressures continues to drag down public approval and cause widespread discontent. Although GDP growth remains steady at 3.4%, the persistent cost-of-living crisis is our primary domestic vulnerability. We must maintain tight monetary policy and increase targeted social welfare and economic support to alleviate popular distress while rebalancing the budget to stabilise prices.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "welfare",
      "order": "Increase welfare spending to 2.5 percent of GDP to ease the burden of high prices on vulnerable populations."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.5,
      "sub": "infrastructure",
      "order": "Boost infrastructure investment to 4.5 percent of GDP to enhance long-term productive capacity and employment."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Raise the policy rate by another 0.5 percentage points to aggressively anchor inflation expectations."
    }
  ],
  "cables": [],
  "public_statement": "My government hears your concerns regarding the cost of living. We are taking decisive action through targeted welfare programs and monetary measures to stabilize prices, protect families, and secure a prosperous economic future for all Nigerians.",
  "standing_orders": [
    {
      "when": "inflation_above:25",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Maintain tight monetary policy by raising the policy rate whenever inflation exceeds 25 percent."
      }
    }
  ],
  "detailed_report": "economy"
}
